CREATE TYPE "PrinterConnectionType" AS ENUM ('BLUETOOTH','USB','NETWORK','LOTTERY_MACHINE');CREATE TYPE "PrinterStatus" AS ENUM ('PENDING','ONLINE','OFFLINE','ERROR','DISABLED');CREATE TYPE "PrintJobStatus" AS ENUM ('QUEUED','PROCESSING','PRINTED','FAILED','CANCELLED');
CREATE TABLE "Printer"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"branchId" UUID NOT NULL REFERENCES "Branch"("id") ON DELETE RESTRICT,"name" VARCHAR(120) NOT NULL,"connectionType" "PrinterConnectionType" NOT NULL,"protocol" VARCHAR(80) NOT NULL DEFAULT 'ESC_POS',"configuration" JSONB NOT NULL,"status" "PrinterStatus" NOT NULL DEFAULT 'PENDING',"isDefault" BOOLEAN NOT NULL DEFAULT false,"lastSeenAt" TIMESTAMPTZ,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "one_default_printer_per_branch" ON "Printer"("tenantId","branchId") WHERE "isDefault"=true AND "status"<>'DISABLED';
CREATE TABLE "PrintTemplate"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"name" VARCHAR(120) NOT NULL,"kind" VARCHAR(30) NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"definition" JSONB NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("tenantId","name","version"));
CREATE TABLE "PrintJob"("id" UUID PRIMARY KEY,"tenantId" UUID NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,"ticketId" UUID NOT NULL REFERENCES "Ticket"("id") ON DELETE RESTRICT,"printerId" UUID NOT NULL REFERENCES "Printer"("id") ON DELETE RESTRICT,"templateId" UUID NOT NULL REFERENCES "PrintTemplate"("id") ON DELETE RESTRICT,"idempotencyKey" VARCHAR(120) NOT NULL,"status" "PrintJobStatus" NOT NULL DEFAULT 'QUEUED',"payload" JSONB NOT NULL,"attempts" INTEGER NOT NULL DEFAULT 0,"maxAttempts" INTEGER NOT NULL DEFAULT 5,"availableAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"lockedAt" TIMESTAMPTZ,"lockedBy" VARCHAR(100),"printedAt" TIMESTAMPTZ,"lastError" TEXT,"createdAt" TIMESTAMPTZ NOT NULL DEFAULT now(),"updatedAt" TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE("tenantId","idempotencyKey"),CHECK("attempts">=0),CHECK("maxAttempts">0));
CREATE INDEX "printer_branch_status" ON "Printer"("tenantId","branchId","status");CREATE INDEX "template_kind_active" ON "PrintTemplate"("tenantId","kind","active");CREATE INDEX "print_queue" ON "PrintJob"("tenantId","status","availableAt");CREATE INDEX "printer_jobs" ON "PrintJob"("printerId","status");
ALTER TABLE "Printer" ENABLE ROW LEVEL SECURITY;ALTER TABLE "PrintTemplate" ENABLE ROW LEVEL SECURITY;ALTER TABLE "PrintJob" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_printer_isolation ON "Printer" USING("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_template_isolation ON "PrintTemplate" USING("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
CREATE POLICY tenant_print_job_isolation ON "PrintJob" USING("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true') WITH CHECK("tenantId"=nullif(current_setting('app.tenant_id',true),'')::uuid OR current_setting('app.is_platform_admin',true)='true');
